style.css:
/* Change the background color and text color for the entire website */
body {
    background-color: #e8d7ac; /* Example: dark gray background */
    color: #423a32; /* Example: white text */
}

/* Optional: Change the color of links */
a {
    color: #00aced; /* Example: bright blue links */
}

/* Optional: Ensure links change color on hover for better visibility */
a:hover {
    color: #ff6347; /* Example: tomato red on hover */
}
